### Function to Determine Characteristics of the nth Fibonacci Number and Check if it's Prime

```python
def nth_fibonacci(n):
    """
    Calculate the nth number in the Fibonacci sequence and check if it's a prime number.

    Args:
        n (int): The position of the Fibonacci number to calculate.

    Returns:
        dict: A dictionary containing the nth Fibonacci number, its parity, and whether it's prime.
    """
    # Initialize the first two Fibonacci numbers
    a, b = 0, 1

    # Check if n is less than or equal to 0
    if n <= 0:
        return {"number": "Fibonacci sequence does not exist for n <= 0", "parity": "N/A", "is_prime": False}

    # Calculate the nth Fibonacci number
    for _ in range(2, n + 1):
        a, b = b, a + b

    # Determine the parity of the nth Fibonacci number
    parity = "Even" if b % 2 == 0 else "Odd"

    # Check if the nth Fibonacci number is prime
    def is_prime(num):
        """Check if a number is prime."""
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    is_prime_number = is_prime(b)

    return {"number": b, "parity": parity, "is_prime": is_prime_number}
```

