```python
def truck_tank_management():
    class Tank:
        def __init__(self, capacity):
            self.capacity = capacity
            self.level = 0

        def fill(self):
            self.level = self.capacity

        def drain(self):
            self.level = 0

        def add_fuel(self, amount):
            if self.level + amount <= self.capacity:
                self.level += amount
            else:
                self.level = self.capacity

        def remove_fuel(self, amount):
            if self.level - amount >= 0:
                self.level -= amount
            else:
                self.level = 0

    class Truck:
        def __init__(self):
            self.main_tank = Tank(100)
            self.additional_tank = Tank(100)
            self.fuel_usage_rate = 5  # liters per kilometer

        def transfer_fuel(self, amount):
            if self.additional_tank.level >= amount:
                self.main_tank.add_fuel(amount)
                self.additional_tank.remove_fuel(amount)
            else:
                print("Not enough fuel in the additional tank.")

        def display_tank_levels(self):
            print(f"Main Tank: {self.main_tank.level}L")
            print(f"Additional Tank: {self.additional_tank.level}L")

        def drive(self, kilometers):
            if self.main_tank.level < self.fuel_usage_rate * kilometers:
                print("Not enough fuel to drive this distance.")
                return
            self.main_tank.remove_fuel(self.fuel_usage_rate * kilometers)
            print(f"Truck has driven {kilometers} kilometers.")

    truck = Truck()
    truck.main_tank.fill()
    truck.additional_tank.fill()

    while True:
        print("\nOptions:")
        print("1. Display tank levels")
        print("2. Transfer fuel from additional tank to main tank")
        print("3. Drive the truck")
        print("4. Quit")

        choice = input("Choose an option: ")

        if choice == "1":
            truck.display_tank_levels()
        elif choice == "2":
            amount = int(input("Enter the amount to transfer: "))
            truck.transfer_fuel(amount)
        elif choice == "3":
            kilometers = int(input("Enter the distance to drive (in kilometers): "))
