def getSmallestStringWithSwaps(a, k):
    # Build the union-find data structure
    parent = list(range(len(a)))
    rank = [0] * len(a)

    def find(x):
        if parent[x]!= x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x!= root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            elif rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    # Perform union-find on all pairs of strings that are anagrams
    for i in range(len(a)):
        for j in range(i+1, len(a)):
            if sorted(a[i]) == sorted(a[j]):
                union(i, j)

    # Group the strings by their roots
    groups = {}
    for i in range(len(a)):
        root = find(i)
        if root not in groups:
            groups[root] = []
        groups[root].append(i)

    # Sort the strings in each group and find the smallest one
    for root in groups:
        group = groups[root]
        group.sort(key=lambda x: a[x])
        groups[root] = group

    # Perform the operations to make all strings lexicographically sorted
    res = []
    for group in groups.values():
        res.extend(a[i] for i in group)

    # Reconstruct the result
    result = []
    for i in range(k):
        result.append(res[i])
    for i in range(k, len(a)):
        result.append(res[i])
    for i in range(k, len(a) - len(res)):
        result.append(res[len(a) - len(result) + i])

    return ''.join(result)
