            print("Invalid input. Please enter a number.")

    # Round the purchase amount to the nearest multiple of 10, rounding up in case of a tie
    rounded_purchase_amount = (round(purchase_amount / 10) + (purchase_amount % 10 >= 5)) * 10

    # Get the starting bank balance from the user
    while True:
        try:
            bank_balance = float(input("Enter your current bank balance: "))
